use super::*;

impl Backend{
 pub(super) fn draft_dir(&self)->Result<PathBuf>{let client=self.client()?;self.prepare_drafts(client.network_id(),client.client_id())}
 pub(super) async fn send_draft(&mut self,conversation_id:String,draft:ComposerDraft,saved:Option<DurableInputDraft>)->Result<()>{ensure!(self.state.can_stage_input(),"此身份尚未完成可写工作区验证，输入保留在编辑器");
 let client=self.client()?.clone();let target_node=self.active_entry.as_ref().context("目标设备未确认")?.node_id.clone();let directory=self.draft_dir()?;let fingerprint=format!("{:x}",Sha256::digest(serde_json::to_vec(&json!({"target_node":target_node,"conversation":conversation_id,"draft":draft}))?));let path=directory.join(format!("{}.json",saved.as_ref().map(|d|d.fingerprint.as_str()).unwrap_or(&fingerprint)));
 let mut saved=if let Some(saved)=saved{saved}else if tokio::fs::try_exists(&path).await?{read_draft(path.clone()).await?}else{
  let bot=self.state.bots.iter().find(|b|b.conversation_id==conversation_id).context("目标 Bot 尚未读取")?;let needs_task=draft.intent==InputIntent::NewTask||matches!(draft.target,InputTarget::ChannelMember{..});let(mut target,mut revision)=(draft.target.clone(),draft.expected_revision);let source_events=if needs_task{if let InputTarget::Work{work_id}=&draft.target{if let Some(detail)=self.state.work_detail.as_ref().filter(|detail|detail.work.work_id==*work_id&&detail.work.conversation_id==conversation_id){detail.work.source_events.clone()}else if self.state.online{let detail=client.read(ReadRequest::Work{conversation_id:conversation_id.clone(),work_id:work_id.clone()}).await?;ensure!(detail["work"]["work_id"]==*work_id&&detail["work"]["conversation_id"]==conversation_id,"工作详情属于其他目标");serde_json::from_value(detail["work"]["source_events"].clone())?}else{self.state.conversation.works.iter().find(|work|work.work_id==*work_id).context("原工作尚未读取")?.source_events.clone()}}else{vec![]}}else{vec![]};let prerequisite=if needs_task{let task_id=uuid::Uuid::new_v4().to_string();let channel_id=match &draft.target{InputTarget::ChannelMember{channel_id,..}|InputTarget::ChannelTask{channel_id,..}=>Some(channel_id.clone()),_=>None};target=if let Some(channel_id)=&channel_id{InputTarget::ChannelTask{channel_id:channel_id.clone(),task_id:task_id.clone(),bot_id:bot.bot_id.clone()}}else{InputTarget::Task{task_id:task_id.clone()}};revision=Some(1);Some(WorkspaceCommand::CreateTask{task_id,channel_id,parent_task_id:None,owner_bot:bot.bot_id.clone(),title:draft.text.lines().next().unwrap_or("附件任务").chars().take(120).collect(),request:draft.text.clone(),expected_result:"按交代完成工作，并说明结果和未完成的部分。".into(),source_events,dependencies:vec![],reply_only:false})}else{None};DurableInputDraft{network_id:client.network_id().into(),client_id:client.client_id().into(),target_node:target_node.clone(),conversation_id:conversation_id.clone(),input:InputRequest{message_id:uuid::Uuid::new_v4().to_string(),route:InputRoute{target,intent:draft.intent,sequence:0,expected_revision:revision},text:draft.text.clone(),attachments:draft.attachments.clone(),report_results:true},prerequisite,prerequisite_id:None,fingerprint}
 };
 ensure!(saved.target_node==target_node&&saved.network_id==client.network_id()&&saved.client_id==client.client_id(),"原输入属于其他网络、身份或Node，须连接原设备后核对");
 client.retain_attachments(&format!("native-input:{}",saved.fingerprint),saved.input.attachments.clone()).await?;write_draft(path.clone(),saved.clone()).await?;
 // Both operations are signed and committed locally before acknowledging the editor.
 // The outbox dependency prevents any generic resend path from bypassing task creation.
 if let Some(command)=saved.prerequisite.clone(){let prerequisite=client.stage(Action::Workspace{command}).await?;saved.prerequisite_id=Some(prerequisite.id);write_draft(path.clone(),saved.clone()).await?;}
 let prerequisites=saved.prerequisite_id.iter().cloned().collect();let staged=client.stage_after(Action::Input{conversation_id:saved.conversation_id.clone(),input:saved.input.clone()},prerequisites).await?;saved.input.route.sequence=staged.sequence.context("本机输入序号未持久化")?;
 write_draft(path.clone(),saved.clone()).await?;self.state.drafts=load_draft_summaries(directory).await?;self.state.pending=client.pending().await?.into_iter().map(|item|Pending{id:item.id,state:operation_label(item.state).into(),target_node:item.target_node}).collect();self.publish();
 let _=self.emit(Event::InputStored(saved.input.text.clone())).await;if let Some(id)=&self.form_id{let _=self.emit(Event::FormSaved(id.clone())).await;}
 let _=self.emit(Event::Notice(if self.state.online{"输入已存本机，等待可写连接或核对前序回执。"}else{"输入已存本机，等待连接；结果未知的原操作只核对，不重发。"}.into())).await;
 if !self.state.writable{return Ok(())}
 let completion=self.completion.clone();let generation=client.generation().to_owned();
 tokio::spawn(async move{let result=async{if let Some(id)=&saved.prerequisite_id{let prerequisite=client.send_staged(id).await?;if prerequisite.state!=vibeface_client::OperationState::Accepted{return Ok(prerequisite)}}let receipt=client.send_staged(&saved.input.message_id).await?;if receipt.state==vibeface_client::OperationState::Accepted{tokio::fs::remove_file(&path).await?;client.release_attachments(&format!("native-input:{}",saved.fingerprint)).await?;}Ok(receipt)}.await;let _=completion.send(Completed{generation,input:None,form_id:None,copy_token:false,delivery:false,result}).await;});Ok(())
 }
 pub(super) async fn flush_prepared(&self)->Result<()>{if !self.state.writable||!self.state.online{return Ok(())}let client=self.client()?.clone();let target=self.active_entry.as_ref().context("原Node入口缺失")?.node_id.clone();let operations=client.pending().await?.into_iter().filter(|operation|operation.state==vibeface_client::OperationState::Prepared&&operation.target_node==target).map(|operation|operation.id).collect::<Vec<_>>();let completion=self.completion.clone();let generation=client.generation().to_owned();tokio::spawn(async move{use futures_util::StreamExt;futures_util::stream::iter(operations).for_each_concurrent(8,|id|{let client=client.clone();let completion=completion.clone();let generation=generation.clone();async move{let result=client.send_staged(&id).await;let _=completion.send(Completed{generation,input:None,form_id:None,copy_token:false,delivery:false,result}).await;}}).await;});Ok(())}
 pub(super) async fn finish_accepted_draft(&self,id:&str)->Result<()>{let directory=self.draft_dir()?;let id=id.to_owned();let removed=tokio::task::spawn_blocking(move||->Result<Vec<String>>{if !directory.try_exists()?{return Ok(vec![])}let mut owners=vec![];for entry in std::fs::read_dir(&directory)?{let path=entry?.path();if path.extension().and_then(|ext|ext.to_str())!=Some("json"){continue}let saved:DurableInputDraft=serde_json::from_slice(&vibeface_bridge::platform::privatefs::read_private_bounded(&path,1024*1024,"原生待发输入")?)?;if saved.input.message_id==id{std::fs::remove_file(path)?;owners.push(format!("native-input:{}",saved.fingerprint));}}Ok(owners)}).await??;for owner in removed{self.client()?.release_attachments(&owner).await?;}Ok(())}
 pub(super) async fn collect_current_attachments(&self)->Result<()>{let mut keep=self.attachments.values().flatten().cloned().collect::<Vec<_>>();keep.extend(load_draft_attachments(self.draft_dir()?).await?);self.client()?.collect_attachments(keep).await}
 pub(super) async fn input_instruction(&mut self,conversation_id:String,bot_id:String,text:String)->Result<()>{self.send_draft(conversation_id,ComposerDraft{target:InputTarget::BotMain{bot_id},intent:InputIntent::Continue,text,attachments:vec![],expected_revision:None},None).await}
}
